package com.luqta.app;

import android.app.*; import android.os.*; import android.graphics.*; import android.graphics.drawable.*; import android.view.*; import android.view.inputmethod.EditorInfo; import android.widget.*; import java.util.*;

public class MainActivity extends Activity {
 int pink=Color.rgb(255,45,141), cyan=Color.rgb(34,211,238), gold=Color.rgb(255,200,87), mint=Color.rgb(67,230,177), bg=Color.rgb(7,8,11), panel=Color.rgb(20,21,28), soft=Color.rgb(35,36,46); LinearLayout root,body; ArrayList<String> fav=new ArrayList<>(); EditText search;
 TextView t(String s,int sp,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextColor(Color.WHITE);v.setTextSize(sp);v.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);v.setPadding(18,12,18,12);if(bold)v.setTypeface(null,1);return v;} GradientDrawable box(int c,float r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(r);return g;} GradientDrawable stroke(int c,int line,float r){GradientDrawable g=box(c,r);g.setStroke(2,line);return g;}
 public void onCreate(Bundle b){super.onCreate(b);showHome();} void base(){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);root.setBackgroundColor(bg);ScrollView sc=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(22,18,22,18);sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));root.addView(nav());setContentView(root);} View logo(){LinearLayout l=new LinearLayout(this);l.setGravity(Gravity.CENTER);TextView a=t("●",18,true);a.setTextColor(cyan);TextView x=t("⌜  لُقطة  ⌟",34,true);TextView z=t("●",18,true);z.setTextColor(pink);l.addView(a);l.addView(x);l.addView(z);return l;} TextView chip(String s,int c){TextView v=t(s,13,true);v.setGravity(Gravity.CENTER);v.setBackground(stroke(Color.rgb(27,28,36),c,40));return v;}
 void showHome(){base();body.addView(logo());TextView sub=t("كل ما تبحث عنه .. في لُقطة واحدة",15,false);sub.setGravity(Gravity.CENTER);sub.setTextColor(Color.LTGRAY);body.addView(sub);LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setBackground(box(panel,38));search=new EditText(this);search.setHint("وش تدور عليه؟");search.setHintTextColor(Color.GRAY);search.setTextColor(Color.WHITE);search.setSingleLine();search.setTextSize(16);search.setBackgroundColor(Color.TRANSPARENT);search.setImeOptions(EditorInfo.IME_ACTION_SEARCH);search.setOnEditorActionListener((v,id,e)->{showResults(search.getText().toString().trim().isEmpty()?"أفضل اللقطات":search.getText().toString());return true;});bar.addView(search,new LinearLayout.LayoutParams(0,68,1));TextView cam=t("📷",24,true);cam.setGravity(Gravity.CENTER);cam.setOnClickListener(v->showCamera());bar.addView(cam,new LinearLayout.LayoutParams(64,64));body.addView(bar);body.addView(t("اكتشف الأقسام",21,true));String[] cats={"👗\nأزياء","📱\nإلكترونيات","🏠\nمنزل ومطبخ","🚗\nسيارات وقطع غيار","✨\nجمال وعناية","⌚\nساعات ومجوهرات","🎮\nألعاب وهوايات","🏃\nرياضة ولياقة","🧸\nأطفال ورضع","🎁\nهدايا"};for(int i=0;i<cats.length;i+=2){LinearLayout r=new LinearLayout(this);for(int j=i;j<Math.min(i+2,cats.length);j++){TextView c=t(cats[j],16,true);c.setGravity(Gravity.CENTER);c.setBackground(stroke(panel,j%3==0?pink:j%3==1?cyan:gold,28));c.setOnClickListener(v->showResults(((TextView)v).getText().toString().replace("\n"," ")));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,105,1);p.setMargins(6,6,6,6);r.addView(c,p);}body.addView(r);}TextView banner=t("✦  لُقطة AI\nصوّر أي شيء يعجبك… ونبحث لك عنه",20,true);banner.setGravity(Gravity.CENTER);banner.setBackground(stroke(Color.rgb(31,18,46),pink,34));banner.setOnClickListener(v->showCamera());LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,145);bp.setMargins(0,14,0,8);body.addView(banner,bp);}
 void showCamera(){base();body.addView(logo());TextView title=t("ابحث بالصورة",25,true);title.setGravity(Gravity.CENTER);body.addView(title);TextView sub=t("صوّر المنتج أو اختر صورة من المعرض",14,false);sub.setGravity(Gravity.CENTER);sub.setTextColor(Color.LTGRAY);body.addView(sub);TextView frame=t("⌜                                      ⌝\n\n\n\n             ضع المنتج هنا\n\n\n\n⌞                                      ⌟",18,true);frame.setGravity(Gravity.CENTER);frame.setBackground(stroke(Color.rgb(12,13,18),cyan,36));body.addView(frame,new LinearLayout.LayoutParams(-1,420));TextView snap=t("●",64,true);snap.setTextColor(pink);snap.setGravity(Gravity.CENTER);snap.setOnClickListener(v->showResults("منتج من الصورة"));body.addView(snap);}
 void showResults(String q){base();body.addView(logo());body.addView(t("نتائج لُقطة",23,true));body.addView(chip("⌕  "+q,pink),new LinearLayout.LayoutParams(-1,55));String[] names={"اختيار مطابق تقريبًا","أفضل سعر اليوم","بديل قريب","خيار موثوق","توصيل أسرع","لقطة اقتصادية"},stores={"نون","Amazon.sa","متجر محلي","متجر متخصص","متجر سعودي","متجر آخر"},prices={"189 ر.س","249 ر.س","299 ر.س","159 ر.س","219 ر.س","129 ر.س"};for(int i=0;i<6;i++){final String nm=names[i];LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(16,13,16,13);card.setBackground(stroke(panel,i%3==0?pink:i%3==1?cyan:gold,28));TextView pic=t("◇   معاينة المنتج   ◇",24,true);pic.setGravity(Gravity.CENTER);pic.setTextColor(i%2==0?cyan:gold);card.addView(pic,new LinearLayout.LayoutParams(-1,118));card.addView(t(names[i],18,true));card.addView(t(stores[i]+"   ★ 4."+(9-i%4),13,false));LinearLayout row=new LinearLayout(this);TextView pr=t(prices[i],20,true);pr.setTextColor(i%2==0?pink:mint);row.addView(pr,new LinearLayout.LayoutParams(0,55,1));TextView heart=t("♡",28,true);heart.setGravity(Gravity.CENTER);heart.setOnClickListener(v->{if(!fav.contains(nm)){fav.add(nm);((TextView)v).setText("♥");}});row.addView(heart,new LinearLayout.LayoutParams(60,55));card.addView(row);LinearLayout actions=new LinearLayout(this);TextView hunt=chip("صِدها لي",gold);hunt.setOnClickListener(v->showHunt(nm));TextView buy=chip("عرض المنتج ←",pink);buy.setOnClickListener(v->Toast.makeText(this,"هنا يفتح رابط المتجر",Toast.LENGTH_SHORT).show());actions.addView(hunt,new LinearLayout.LayoutParams(0,55,1));actions.addView(buy,new LinearLayout.LayoutParams(0,55,1));card.addView(actions);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.setMargins(0,7,0,7);body.addView(card,cp);}}
 void showFavorites(){base();body.addView(logo());body.addView(t("المفضلة",25,true));if(fav.isEmpty()){TextView e=t("♡\nما حفظت أي لُقطة للحين\nاضغط القلب عند أي منتج يعجبك",18,false);e.setGravity(Gravity.CENTER);e.setTextColor(Color.LTGRAY);body.addView(e,new LinearLayout.LayoutParams(-1,330));}else for(String s:fav){TextView v=t("♥  "+s,18,true);v.setBackground(box(panel,24));body.addView(v,new LinearLayout.LayoutParams(-1,75));}}
 void showHunt(String item){base();body.addView(logo());body.addView(t("صِدها لي",25,true));TextView info=t("نراقب السعر وننبهك إذا وصل لهدفك.\n\nالمنتج: "+item,17,false);info.setBackground(box(panel,26));body.addView(info,new LinearLayout.LayoutParams(-1,130));EditText target=new EditText(this);target.setHint("السعر المستهدف — مثال 150 ر.س");target.setHintTextColor(Color.GRAY);target.setTextColor(Color.WHITE);target.setBackground(stroke(panel,gold,24));body.addView(target,new LinearLayout.LayoutParams(-1,70));TextView save=t("فعّل التنبيه",18,true);save.setGravity(Gravity.CENTER);save.setBackground(stroke(Color.rgb(50,38,15),gold,28));save.setOnClickListener(v->Toast.makeText(this,"تم حفظ هدف السعر ✓",Toast.LENGTH_LONG).show());body.addView(save,new LinearLayout.LayoutParams(-1,65));}
 void showAccount(){base();body.addView(logo());body.addView(t("حسابي",25,true));String[] rows={"👤  زائر لُقطة","🔔  تنبيهات الأسعار","⚙  الإعدادات","؟  المساعدة","ℹ  عن لُقطة"};for(String s:rows){TextView r=t(s+"     ‹",17,true);r.setBackground(box(panel,22));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,70);p.setMargins(0,5,0,5);body.addView(r,p);}}
 View nav(){LinearLayout n=new LinearLayout(this);n.setGravity(Gravity.CENTER);n.setPadding(6,5,6,5);n.setBackgroundColor(Color.rgb(13,14,19));String[] x={"⌂\nالرئيسية","♡\nالمفضلة","◎\nصِدها لي","●\nحسابي"};for(String s:x){TextView v=t(s,13,false);v.setGravity(Gravity.CENTER);v.setOnClickListener(z->{String q=((TextView)z).getText().toString();if(q.contains("الرئيسية"))showHome();else if(q.contains("المفضلة"))showFavorites();else if(q.contains("صِدها"))showHunt("اختر منتجًا من نتائج البحث");else showAccount();});n.addView(v,new LinearLayout.LayoutParams(0,72,1));}return n;}
}
